function rowWithMostOnes(grid: number[][]): number[] {
  let bestRow = 0, bestCount = -1;
  for (let r = 0; r < grid.length; r++) {
    let count = 0;
    for (const v of grid[r]) count += v;
    if (count > bestCount) {
      bestRow = r;
      bestCount = count;
    }
  }
  return [bestRow, bestCount];
}

