class Solution:
    def rowWithMostOnes(self, grid: List[List[int]]) -> List[int]:
        best_row, best_count = 0, -1
        for r, row in enumerate(grid):
            count = sum(row)
            if count > best_count:
                best_row, best_count = r, count
        return [best_row, best_count]

